import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { createHash } from 'node:crypto';
import { access, readFile, readdir } from 'node:fs/promises';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);
const canonicalRelease = JSON.parse(await readFile(
  new URL('../../downloads/formal-publication-release.json', import.meta.url),
  'utf8',
));
const CORE_COMMIT = canonicalRelease.source.commit;
const CORE_TREE = canonicalRelease.source.tree;
const STATUS_COORDINATE = canonicalRelease.artifacts.status.coordinate;
const INVENTORY_COORDINATE = canonicalRelease.artifacts.theoremInventory.coordinate;
const INVENTORY_SHA256 = canonicalRelease.artifacts.theoremInventory.sha256;
const INVENTORY_BYTES = canonicalRelease.artifacts.theoremInventory.bytes;
const formatNumber = (value) => new Intl.NumberFormat('en-US').format(value);
const CURRENT_PROSE_STOP_WORDS = new Set([
  'about', 'after', 'again', 'against', 'also', 'being', 'could', 'does',
  'every', 'from', 'have', 'into', 'itself', 'milestone', 'only', 'other',
  'result', 'same', 'than', 'that', 'their', 'there', 'these', 'this',
  'through', 'under', 'where', 'which', 'with', 'without',
]);
const significantCurrentProseConcepts = (value) => [...new Set(
  value
    .replaceAll(/<[^>]*>/gu, ' ')
    .replaceAll(/&[a-z0-9#]+;/giu, ' ')
    .toLowerCase()
    .match(/[a-z0-9]+/gu)
    ?.filter((word) => word.length >= 5 && !CURRENT_PROSE_STOP_WORDS.has(word)) ?? []
)];
const assertCurrentProseCoverage = (actual, canonical, minimum, label) => {
  const actualText = actual.toLowerCase();
  const concepts = significantCurrentProseConcepts(canonical);
  const present = concepts.filter((concept) => actualText.includes(concept));
  assert.ok(concepts.length > 0, `${label}: canonical record has no testable concepts`);
  assert.ok(
    present.length / concepts.length >= minimum,
    `${label}: expected at least ${Math.round(minimum * 100)}% canonical concept coverage; missing ${concepts.filter((concept) => !actualText.includes(concept)).join(', ')}`,
  );
};
const MILESTONE_FIELD_PARTS = Object.freeze({
  bn4: 'BN4',
  bn5: 'BN5',
  hb: 'HB',
  hn: 'HN',
  hresolve: 'HResolve',
  pccpack: 'PCCPack',
});
const milestoneFieldStem = (milestoneId) => milestoneId
  .split('-')
  .map((part) => MILESTONE_FIELD_PARTS[part] ?? `${part[0].toUpperCase()}${part.slice(1)}`)
  .join('');
const releaseBoundaryPrefixForMilestone = (release, milestone) => {
  const suffix = 'TheoremKernelTypeSha256';
  const requiredTheorems = new Set(milestone.requiredTheorems);
  const matchingField = Object.entries(release.earnedBoundary).find(
    ([key, value]) => key.endsWith(suffix)
      && value !== null
      && typeof value === 'object'
      && !Array.isArray(value)
      && Object.keys(value).length === requiredTheorems.size
      && [...requiredTheorems].every((name) => Object.hasOwn(value, name)),
  );
  assert.ok(matchingField, `missing earned-boundary fingerprint map for ${milestone.id}`);
  return matchingField[0].slice(0, -suffix.length);
};
const statusStemForReleaseBoundary = (status, release, prefix) => {
  const scope = release.earnedBoundary[`${prefix}Scope`];
  const scopeKeys = Object.keys(status).filter(
    (key) => key.startsWith('lean') && key.endsWith('Scope') && status[key] === scope,
  );
  assert.equal(scopeKeys.length, 1, `expected one status scope field for ${prefix}`);
  return scopeKeys[0].slice('lean'.length, -'Scope'.length);
};
